File or Folder Display

Show the structure of directory
# path; depth: Depth of folder displayed; current_depth
# import os
def print_tree(path, depth=1, current_depth=0):
    if current_depth &gt; depth:
        return
    for item in os.listdir(path):
        item_path = os.path.join(path, item)
        print("    " * current_depth + "|-- " + item)
        if os.path.isdir(item_path):
            print_tree(item_path, depth, current_depth + 1)


Counts the files in the directory
# import os
def count_files_in_directory(directory_path):
    files = [f for f in os.listdir(directory_path) if os.path.isfile(os.path.join(directory_path, f))]
    return len(files)
